typedef long long ll;

ll min(ll a, ll b) { return a < b ? a : b; }
ll max(ll a, ll b) { return a > b ? a : b; }

int main() {
    int n;
    scanf("%d", &n);

    ll x0[100000], y0[100000];
    char dir[100000];

    for (int i = 0; i < n; i++) {
        scanf("%lld %lld %c", &x0[i], &y0[i], &dir[i]);
    }

    // We'll collect all candidate times
    double times[200000];
    int tcnt = 0;
    times[tcnt++] = 0.0;

    // For x direction: candidates when two x coordinates become equal
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            // Check if they can meet in x
            int di = 0, dj = 0;
            if (dir[i] == 'R') di = 1;
            else if (dir[i] == 'L') di = -1;
            if (dir[j] == 'R') dj = 1;
            else if (dir[j] == 'L') dj = -1;

            if (di != dj) {
                // x0[i] + di*t = x0[j] + dj*t -> t = (x0[j] - x0[i]) / (di - dj)
                if (di - dj != 0) {
                    double t = (double)(x0[j] - x0[i]) / (di - dj);
                    if (t >= 0) times[tcnt++] = t;
                }
            }

            // Check y meeting
            di = 0; dj = 0;
            if (dir[i] == 'U') di = 1;
            else if (dir[i] == 'D') di = -1;
            if (dir[j] == 'U') dj = 1;
            else if (dir[j] == 'D') dj = -1;

            if (di != dj && di - dj != 0) {
                double t = (double)(y0[j] - y0[i]) / (di - dj);
                if (t >= 0) times[tcnt++] = t;
            }
        }
    }

    // Also add times slightly after each candidate to catch minima between events
    int original_cnt = tcnt;
    for (int i = 0; i < original_cnt; i++) {
        times[tcnt++] = times[i] + 1e-7;
    }

    ll ans = LLONG_MAX;

    for (int ti = 0; ti < tcnt; ti++) {
        double t = times[ti];
        ll xmin = LLONG_MAX, xmax = LLONG_MIN;
        ll ymin = LLONG_MAX, ymax = LLONG_MIN;

        for (int i = 0; i < n; i++) {
            ll x = x0[i], y = y0[i];
            if (dir[i] == 'R') x = x0[i] + (ll)(t + 1e-9);
            else if (dir[i] == 'L') x = x0[i] - (ll)(t + 1e-9);
            else if (dir[i] == 'U') y = y0[i] + (ll)(t + 1e-9);
            else if (dir[i] == 'D') y = y0[i] - (ll)(t + 1e-9);

            if (x < xmin) xmin = x;
            if (x > xmax) xmax = x;
            if (y < ymin) ymin = y;
            if (y > ymax) ymax = y;
        }

        ll area = (xmax - xmin) * (ymax - ymin);
        if (area < ans) ans = area;
    }

    printf("%lld\n", ans);

    return 0;
}

