#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    double a, b;
} Line; /* value(t) = a + b*t */

typedef struct {
    ll x, y;
    char d[2];
} Point;

static const double INF = 1e30;
static const double EPS = 1e-12;

double min2(double a, double b) { return a < b ? a : b; }
double max2(double a, double b) { return a > b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    /* For x:
       R: x+t
       L: x-t
       U/D: x
       For y:
       U: y+t
       D: y-t
       L/R: y
    */
    double minXR = INF, maxXR = -INF;
    double minXL = INF, maxXL = -INF;
    double minX0 = INF, maxX0 = -INF;

    double minYU = INF, maxYU = -INF;
    double minYD = INF, maxYD = -INF;
    double minY0 = INF, maxY0 = -INF;

    for (int i = 0; i < N; i++) {
        ll x, y;
        char d[2];
        scanf("%lld %lld %s", &x, &y, d);

        if (d[0] == 'R') {
            if (x < minXR) minXR = x;
            if (x > maxXR) maxXR = x;
            if (y < minY0) minY0 = y;
            if (y > maxY0) maxY0 = y;
        } else if (d[0] == 'L') {
            if (x < minXL) minXL = x;
            if (x > maxXL) maxXL = x;
            if (y < minY0) minY0 = y;
            if (y > maxY0) maxY0 = y;
        } else if (d[0] == 'U') {
            if (x < minX0) minX0 = x;
            if (x > maxX0) maxX0 = x;
            if (y < minYU) minYU = y;
            if (y > maxYU) maxYU = y;
        } else { /* D */
            if (x < minX0) minX0 = x;
            if (x > maxX0) maxX0 = x;
            if (y < minYD) minYD = y;
            if (y > maxYD) maxYD = y;
        }
    }

    /* Candidate lines for x_min, x_max, y_min, y_max */
    Line xMinCand[3];
    int xMinCnt = 0;
    if (minXR < INF) xMinCand[xMinCnt++] = (Line){minXR, 1.0};
    if (minXL < INF) xMinCand[xMinCnt++] = (Line){minXL, -1.0};
    if (minX0 < INF) xMinCand[xMinCnt++] = (Line){minX0, 0.0};

    Line xMaxCand[3];
    int xMaxCnt = 0;
    if (maxXR > -INF) xMaxCand[xMaxCnt++] = (Line){maxXR, 1.0};
    if (maxXL > -INF) xMaxCand[xMaxCnt++] = (Line){maxXL, -1.0};
    if (maxX0 > -INF) xMaxCand[xMaxCnt++] = (Line){maxX0, 0.0};

    Line yMinCand[3];
    int yMinCnt = 0;
    if (minYU < INF) yMinCand[yMinCnt++] = (Line){minYU, 1.0};
    if (minYD < INF) yMinCand[yMinCnt++] = (Line){minYD, -1.0};
    if (minY0 < INF) yMinCand[yMinCnt++] = (Line){minY0, 0.0};

    Line yMaxCand[3];
    int yMaxCnt = 0;
    if (maxYU > -INF) yMaxCand[yMaxCnt++] = (Line){maxYU, 1.0};
    if (maxYD > -INF) yMaxCand[yMaxCnt++] = (Line){maxYD, -1.0};
    if (maxY0 > -INF) yMaxCand[yMaxCnt++] = (Line){maxY0, 0.0};

    /* Collect all critical times:
       t=0 and intersections among candidate lines for each envelope.
       Between critical times, width and height are linear, so area is quadratic.
       Since width,height >= 0, area on an interval is convex enough here to check endpoints
       and stationary point of quadratic.
    */
    double times[100];
    int tc = 0;
    times[tc++] = 0.0;

    /* helper macro to add intersection times */
    #define ADD_INTERSECTIONS(arr, cnt) \
        do { \
            for (int i = 0; i < (cnt); i++) { \
                for (int j = i + 1; j < (cnt); j++) { \
                    double db = (arr)[i].b - (arr)[j].b; \
                    if (db > EPS || db < -EPS) { \
                        double t = ((arr)[j].a - (arr)[i].a) / db; \
                        if (t >= -EPS) times[tc++] = t < 0 ? 0 : t; \
                    } \
                } \
            } \
        } while (0)

    ADD_INTERSECTIONS(xMinCand, xMinCnt);
    ADD_INTERSECTIONS(xMaxCand, xMaxCnt);
    ADD_INTERSECTIONS(yMinCand, yMinCnt);
    ADD_INTERSECTIONS(yMaxCand, yMaxCnt);

    /* sort and unique */
    for (int i = 0; i < tc; i++) {
        for (int j = i + 1; j < tc; j++) {
            if (times[j] < times[i]) {
                double tmp = times[i];
                times[i] = times[j];
                times[j] = tmp;
            }
        }
    }

    double uniq[100];
    int uc = 0;
    for (int i = 0; i < tc; i++) {
        if (uc == 0 || times[i] - uniq[uc - 1] > 1e-10) {
            uniq[uc++] = times[i];
        }
    }

    double ans = INF;

    for (int seg = 0; seg < uc; seg++) {
        double L = uniq[seg];
        double R = (seg + 1 < uc ? uniq[seg + 1] : -1.0);

        double sample;
        if (R < 0) sample = L + 1.0;
        else sample = (L + R) * 0.5;

        /* Determine active lines on this interval */
        double xminv = INF, xmaxv = -INF, yminv = INF, ymaxv = -INF;
        Line xminLine = {0, 0}, xmaxLine = {0, 0}, yminLine = {0, 0}, ymaxLine = {0, 0};

        for (int i = 0; i < xMinCnt; i++) {
            double v = xMinCand[i].a + xMinCand[i].b * sample;
            if (v < xminv) {
                xminv = v;
                xminLine = xMinCand[i];
            }
        }
        for (int i = 0; i < xMaxCnt; i++) {
            double v = xMaxCand[i].a + xMaxCand[i].b * sample;
            if (v > xmaxv) {
                xmaxv = v;
                xmaxLine = xMaxCand[i];
            }
        }
        for (int i = 0; i < yMinCnt; i++) {
            double v = yMinCand[i].a + yMinCand[i].b * sample;
            if (v < yminv) {
                yminv = v;
                yminLine = yMinCand[i];
            }
        }
        for (int i = 0; i < yMaxCnt; i++) {
            double v = yMaxCand[i].a + yMaxCand[i].b * sample;
            if (v > ymaxv) {
                ymaxv = v;
                ymaxLine = yMaxCand[i];
            }
        }

        /* width(t) = wx0 + wx1*t, height(t) = hy0 + hy1*t */
        double wx0 = xmaxLine.a - xminLine.a;
        double wx1 = xmaxLine.b - xminLine.b;
        double hy0 = ymaxLine.a - yminLine.a;
        double hy1 = ymaxLine.b - yminLine.b;

        /* area(t) = (wx0+wx1 t)(hy0+hy1 t) = A t^2 + B t + C */
        double A = wx1 * hy1;
        double B = wx0 * hy1 + wx1 * hy0;
        double C = wx0 * hy0;

        /* check endpoints */
        double cand = A * L * L + B * L + C;
        if (cand < ans) ans = cand;

        if (R >= 0) {
            cand = A * R * R + B * R + C;
            if (cand < ans) ans = cand;

            if (A > EPS || A < -EPS) {
                double t0 = -B / (2.0 * A);
                if (t0 > L + 1e-10 && t0 < R - 1e-10) {
                    cand = A * t0 * t0 + B * t0 + C;
                    if (cand < ans) ans = cand;
                }
            }
        } else {
            /* last interval [L, +inf): since widths/heights are linear and nonnegative,
               minimum on this interval is at L or stationary point if A>0 and t0>=L. */
            if (A > EPS) {
                double t0 = -B / (2.0 * A);
                if (t0 > L + 1e-10) {
                    cand = A * t0 * t0 + B * t0 + C;
                    if (cand < ans) ans = cand;
                }
            }
        }
    }

    printf("%.10f\n", ans);
    return 0;
}

