struct Point {
    int64 x, y;
    char dir;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<Point> pts(N);
    for (int i = 0; i < N; i++) {
        cin >> pts[i].x >> pts[i].y >> pts[i].dir;
    }

    // Precompute x(t) and y(t) for each point
    auto get_x = [&](int i, double t) -> double {
        if (pts[i].dir == 'R') return pts[i].x + t;
        if (pts[i].dir == 'L') return pts[i].x - t;
        return pts[i].x;
    };
    auto get_y = [&](int i, double t) -> double {
        if (pts[i].dir == 'U') return pts[i].y + t;
        if (pts[i].dir == 'D') return pts[i].y - t;
        return pts[i].y;
    };

    // Gather all candidate times where min or max might change
    vector<double> times = {0.0};
    // Intersections of x coordinates
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            // Check if x coordinates can become equal
            // xi + vxi*t = xj + vxj*t => t = (xj - xi) / (vxi - vxj)
            int vxi = (pts[i].dir == 'R') - (pts[i].dir == 'L');
            int vxj = (pts[j].dir == 'R') - (pts[j].dir == 'L');
            if (vxi != vxj) {
                double t = double(pts[j].x - pts[i].x) / (vxi - vxj);
                if (t >= 0) times.push_back(t);
            }
            // Check y coordinates
            int vyi = (pts[i].dir == 'U') - (pts[i].dir == 'D');
            int vyj = (pts[j].dir == 'U') - (pts[j].dir == 'D');
            if (vyi != vyj) {
                double t = double(pts[j].y - pts[i].y) / (vyi - vyj);
                if (t >= 0) times.push_back(t);
            }
        }
    }

    sort(times.begin(), times.end());
    double ans = 1e30;

    // Evaluate at each candidate time and also a little after to catch piecewise linear minima
    for (double t0 : times) {
        for (double eps : {-1e-9, 0.0, 1e-9}) {
            double t = t0 + eps;
            if (t < 0) continue;
            double xmin = 1e30, xmax = -1e30;
            double ymin = 1e30, ymax = -1e30;
            for (int i = 0; i < N; i++) {
                double x = get_x(i, t);
                double y = get_y(i, t);
                xmin = min(xmin, x);
                xmax = max(xmax, x);
                ymin = min(ymin, y);
                ymax = max(ymax, y);
            }
            ans = min(ans, (xmax - xmin) * (ymax - ymin));
        }
    }

    cout << fixed << setprecision(0) << ans << "\n";
    return 0;
}

