int main(){
    int n;
    cin >> n;
    vector<double> px(n), py(n);
    vector<char> dir(n);
    for(int i=0;i<n;i++) cin >> px[i] >> py[i] >> dir[i];

    auto calc = [&](double t) -> double {
        double xmx=-1e18,xmn=1e18,ymx=-1e18,ymn=1e18;
        for(int i=0;i<n;i++){
            double x=px[i],y=py[i];
            if(dir[i]=='R') x+=t;
            else if(dir[i]=='L') x-=t;
            else if(dir[i]=='U') y+=t;
            else y-=t;
            xmx=max(xmx,x); xmn=min(xmn,x);
            ymx=max(ymx,y); ymn=min(ymn,y);
        }
        return (xmx-xmn)*(ymx-ymn);
    };

    vector<double> ts;
    ts.push_back(0);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        // x lines: px[i]+s*di vs px[j]+s*dj where s in {-1,0,1}
        auto sx=[&](int k)->double{return dir[k]=='R'?1:dir[k]=='L'?-1:0;};
        auto sy=[&](int k)->double{return dir[k]=='U'?1:dir[k]=='D'?-1:0;};
        double dsx=sx(i)-sx(j), dsy=sy(i)-sy(j);
        if(abs(dsx)>1e-9){double t=(px[j]-px[i])/dsx; if(t>0) ts.push_back(t);}
        if(abs(dsy)>1e-9){double t=(py[j]-py[i])/dsy; if(t>0) ts.push_back(t);}
    }
    sort(ts.begin(),ts.end());
    ts.erase(unique(ts.begin(),ts.end()),ts.end());

    double ans=calc(0);
    for(int i=0;i+1<(int)ts.size();i++){
        double lo=ts[i],hi=ts[i+1],mid=(lo+hi)/2;
        // quadratic minimum
        double a=calc(lo),b=calc(mid),c=calc(hi);
        // fit quadratic through lo,mid,hi
        double t_opt=mid-(b-a)/(2*(c-2*b+a)+1e-18)*(hi-lo)/2; // rough
        if(t_opt>lo&&t_opt<hi) ans=min(ans,calc(t_opt));
        ans=min(ans,min(a,c));
    }
    ans=min(ans,calc(ts.back()));
    printf("%.10f\n",ans);
}

