using int64 = long long;
using ld = long double;

struct Line {
    // value(t) = a + b * t
    ld a, b;
};

static ld eval(const Line& L, ld t) {
    return L.a + L.b * t;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    const ld INF = 1e30L;

    // For x:
    // R: x+t, L: x-t, U/D: x
    ld minA_x_max[3], maxA_x_max[3]; // not used directly, kept for clarity
    ld minA_x_min[3], maxA_x_min[3];

    // We'll store extrema of initial x among groups by slope:
    // slope +1 : R
    // slope -1 : L
    // slope  0 : U,D
    ld max_x_p = -INF, max_x_m = -INF, max_x_0 = -INF;
    ld min_x_p = INF,  min_x_m = INF,  min_x_0 = INF;

    // For y:
    // U: y+t, D: y-t, L/R: y
    ld max_y_p = -INF, max_y_m = -INF, max_y_0 = -INF;
    ld min_y_p = INF,  min_y_m = INF,  min_y_0 = INF;

    for (int i = 0; i < N; ++i) {
        ld x, y;
        char d;
        cin >> x >> y >> d;

        if (d == 'R') {
            max_x_p = max(max_x_p, x);
            min_x_p = min(min_x_p, x);

            max_y_0 = max(max_y_0, y);
            min_y_0 = min(min_y_0, y);
        } else if (d == 'L') {
            max_x_m = max(max_x_m, x);
            min_x_m = min(min_x_m, x);

            max_y_0 = max(max_y_0, y);
            min_y_0 = min(min_y_0, y);
        } else if (d == 'U') {
            max_x_0 = max(max_x_0, x);
            min_x_0 = min(min_x_0, x);

            max_y_p = max(max_y_p, y);
            min_y_p = min(min_y_p, y);
        } else { // 'D'
            max_x_0 = max(max_x_0, x);
            min_x_0 = min(min_x_0, x);

            max_y_m = max(max_y_m, y);
            min_y_m = min(min_y_m, y);
        }
    }

    vector<Line> candMaxX, candMinX, candMaxY, candMinY;

    if (max_x_p > -INF/2) candMaxX.push_back({max_x_p, +1});
    if (max_x_m > -INF/2) candMaxX.push_back({max_x_m, -1});
    if (max_x_0 > -INF/2) candMaxX.push_back({max_x_0, 0});

    if (min_x_p < INF/2) candMinX.push_back({min_x_p, +1});
    if (min_x_m < INF/2) candMinX.push_back({min_x_m, -1});
    if (min_x_0 < INF/2) candMinX.push_back({min_x_0, 0});

    if (max_y_p > -INF/2) candMaxY.push_back({max_y_p, +1});
    if (max_y_m > -INF/2) candMaxY.push_back({max_y_m, -1});
    if (max_y_0 > -INF/2) candMaxY.push_back({max_y_0, 0});

    if (min_y_p < INF/2) candMinY.push_back({min_y_p, +1});
    if (min_y_m < INF/2) candMinY.push_back({min_y_m, -1});
    if (min_y_0 < INF/2) candMinY.push_back({min_y_0, 0});

    auto add_cross_times = [&](const vector<Line>& v, vector<ld>& times) {
        int m = (int)v.size();
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                ld db = v[i].b - v[j].b;
                if (fabsl(db) < 1e-18L) continue;
                ld t = (v[j].a - v[i].a) / db;
                if (t >= 0) times.push_back(t);
            }
        }
    };

    vector<ld> times;
    times.push_back(0);

    add_cross_times(candMaxX, times);
    add_cross_times(candMinX, times);
    add_cross_times(candMaxY, times);
    add_cross_times(candMinY, times);

    auto widthX = [&](ld t) -> ld {
        ld mx = -INF, mn = INF;
        for (auto &L : candMaxX) mx = max(mx, eval(L, t));
        for (auto &L : candMinX) mn = min(mn, eval(L, t));
        return mx - mn;
    };

    auto widthY = [&](ld t) -> ld {
        ld mx = -INF, mn = INF;
        for (auto &L : candMaxY) mx = max(mx, eval(L, t));
        for (auto &L : candMinY) mn = min(mn, eval(L, t));
        return mx - mn;
    };

    ld ans = 1e100L;
    for (ld t : times) {
        ld wx = widthX(t);
        ld wy = widthY(t);
        ans = min(ans, wx * wy);
    }

    cout << fixed << setprecision(15) << (double)ans << '\n';
    return 0;
}

