        char[] d = new char[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextLong();
            y[i] = sc.nextLong();
            d[i] = sc.next().charAt(0);
        }

        // Collect candidate times
        Set<Double> times = new HashSet<>();
        times.add(0.0);

        // x direction candidates
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                // x coordinate equality
                if (x[i] == x[j]) {
                    if ((d[i] == 'L' && d[j] == 'R') || (d[i] == 'R' && d[j] == 'L')) {
                        times.add(0.0);
                    }
                } else {
                    if (d[i] == 'R' && d[j] == 'L' && x[i] < x[j]) {
                        times.add((x[j] - x[i]) / 2.0);
                    }
                    if (d[i] == 'L' && d[j] == 'R' && x[i] > x[j]) {
                        times.add((x[i] - x[j]) / 2.0);
                    }
                }
                // y coordinate equality
                if (y[i] == y[j]) {
                    if ((d[i] == 'D' && d[j] == 'U') || (d[i] == 'U' && d[j] == 'D')) {
                        times.add(0.0);
                    }
                } else {
                    if (d[i] == 'U' && d[j] == 'D' && y[i] < y[j]) {
                        times.add((y[j] - y[i]) / 2.0);
                    }
                    if (d[i] == 'D' && d[j] == 'U' && y[i] > y[j]) {
                        times.add((y[i] - y[j]) / 2.0);
                    }
                }
            }
        }

        double ans = Double.MAX_VALUE;
        for (double t : times) {
            if (t < 0) continue;
            double minX = Double.MAX_VALUE, maxX = -Double.MAX_VALUE;
            double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
            for (int i = 0; i < N; i++) {
                double cx = x[i], cy = y[i];
                if (d[i] == 'R') cx += t;
                else if (d[i] == 'L') cx -= t;
                else if (d[i] == 'U') cy += t;
                else if (d[i] == 'D') cy -= t;
                if (cx < minX) minX = cx;
                if (cx > maxX) maxX = cx;
                if (cy < minY) minY = cy;
                if (cy > maxY) maxY = cy;
            }
            double area = (maxX - minX) * (maxY - minY);
            if (area < ans) ans = area;
        }

        System.out.printf("%.10f%n", ans);
    }
}

