public class Main {
    static int N;
    static double[] px, py, vx, vy;

    static double xmax(double t) { double m = Double.NEGATIVE_INFINITY; for(int i=0;i<N;i++) m=Math.max(m,px[i]+vx[i]*t); return m; }
    static double xmin(double t) { double m = Double.POSITIVE_INFINITY; for(int i=0;i<N;i++) m=Math.min(m,px[i]+vx[i]*t); return m; }
    static double ymax(double t) { double m = Double.NEGATIVE_INFINITY; for(int i=0;i<N;i++) m=Math.max(m,py[i]+vy[i]*t); return m; }
    static double ymin(double t) { double m = Double.POSITIVE_INFINITY; for(int i=0;i<N;i++) m=Math.min(m,py[i]+vy[i]*t); return m; }
    static double eval(double t) { return (xmax(t)-xmin(t))*(ymax(t)-ymin(t)); }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        px=new double[N]; py=new double[N]; vx=new double[N]; vy=new double[N];
        for(int i=0;i<N;i++){
            px[i]=sc.nextDouble(); py[i]=sc.nextDouble();
            String d=sc.next();
            if(d.equals("R")){vx[i]=1;vy[i]=0;}else if(d.equals("L")){vx[i]=-1;vy[i]=0;}else if(d.equals("U")){vx[i]=0;vy[i]=1;}else{vx[i]=0;vy[i]=-1;}
        }
        List<Double> times = new ArrayList<>();
        times.add(0.0);
        for(int i=0;i<N;i++) for(int j=i+1;j<N;j++){
            double dv,dt;
            dv=vx[i]-vx[j]; if(dv!=0){dt=(px[j]-px[i])/dv; if(dt>0) times.add(dt);}
            dv=vy[i]-vy[j]; if(dv!=0){dt=(py[j]-py[i])/dv; if(dt>0) times.add(dt);}
        }
        Collections.sort(times);
        double ans = eval(0);
        for(int i=0;i<times.size();i++){
            ans=Math.min(ans,eval(times.get(i)));
            if(i+1<times.size()){double mid=(times.get(i)+times.get(i+1))/2; ans=Math.min(ans,eval(mid));}
        }
        // Also try ternary search in each interval
        for(int i=0;i<times.size()-1;i++){
            double lo=times.get(i),hi=times.get(i+1);
            for(int k=0;k<200;k++){double m1=lo+(hi-lo)/3,m2=hi-(hi-lo)/3;if(eval(m1)<eval(m2))hi=m2;else lo=m1;}
            ans=Math.min(ans,eval((lo+hi)/2));
        }
        System.out.printf("%.10f%n", ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static final long INF = (long) 4e18;
    static final double EPS = 1e-12;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        long minX0 = INF, maxX0 = -INF;
        long minXR = INF, maxXR = -INF;
        long minXL = INF, maxXL = -INF;

        long minY0 = INF, maxY0 = -INF;
        long minYU = INF, maxYU = -INF;
        long minYD = INF, maxYD = -INF;

        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            char d = fs.next().charAt(0);

            if (d == 'R') {
                minXR = Math.min(minXR, x);
                maxXR = Math.max(maxXR, x);
                minY0 = Math.min(minY0, y);
                maxY0 = Math.max(maxY0, y);
            } else if (d == 'L') {
                minXL = Math.min(minXL, x);
                maxXL = Math.max(maxXL, x);
                minY0 = Math.min(minY0, y);
                maxY0 = Math.max(maxY0, y);
            } else if (d == 'U') {
                minX0 = Math.min(minX0, x);
                maxX0 = Math.max(maxX0, x);
                minYU = Math.min(minYU, y);
                maxYU = Math.max(maxYU, y);
            } else { // 'D'
                minX0 = Math.min(minX0, x);
                maxX0 = Math.max(maxX0, x);
                minYD = Math.min(minYD, y);
                maxYD = Math.max(maxYD, y);
            }
        }

        ArrayList<Double> cand = new ArrayList<>();
        cand.add(0.0);

        // width(t) = max(maxXR+t, maxX0, maxXL-t) - min(minXR+t, minX0, minXL-t)
        addCandidates(cand, maxXR, +1, maxX0, 0);
        addCandidates(cand, maxXR, +1, maxXL, -1);
        addCandidates(cand, maxX0, 0, maxXL, -1);

        addCandidates(cand, minXR, +1, minX0, 0);
        addCandidates(cand, minXR, +1, minXL, -1);
        addCandidates(cand, minX0, 0, minXL, -1);

        // height(t) = max(maxYU+t, maxY0, maxYD-t) - min(minYU+t, minY0, minYD-t)
        addCandidates(cand, maxYU, +1, maxY0, 0);
        addCandidates(cand, maxYU, +1, maxYD, -1);
        addCandidates(cand, maxY0, 0, maxYD, -1);

        addCandidates(cand, minYU, +1, minY0, 0);
        addCandidates(cand, minYU, +1, minYD, -1);
        addCandidates(cand, minY0, 0, minYD, -1);

        double ans = Double.POSITIVE_INFINITY;
        for (double t : cand) {
            if (t < -EPS) continue;
            double w = width(t, minXR, minX0, minXL, maxXR, maxX0, maxXL);
            double h = height(t, minYU, minY0, minYD, maxYU, maxY0, maxYD);
            ans = Math.min(ans, w * h);
        }

        System.out.printf("%.15f%n", ans);
    }

    static void addCandidates(ArrayList<Double> cand, long a, int sa, long b, int sb) {
        if (sa == sb) return;
        double t = (double)(b - a) / (sa - sb);
        if (t >= -EPS) cand.add(Math.max(0.0, t));
    }

    static double width(double t,
                        long minXR, long minX0, long minXL,
                        long maxXR, long maxX0, long maxXL) {
        double mx = -1e100;
        double mn = 1e100;

        if (maxXR != INF) mx = Math.max(mx, maxXR + t);
        if (maxX0 != -INF) mx = Math.max(mx, maxX0);
        if (maxXL != -INF) mx = Math.max(mx, maxXL - t);

        if (minXR != INF) mn = Math.min(mn, minXR + t);
        if (minX0 != INF) mn = Math.min(mn, minX0);
        if (minXL != INF) mn = Math.min(mn, minXL - t);

        return mx - mn;
    }

    static double height(double t,
                         long minYU, long minY0, long minYD,
                         long maxYU, long maxY0, long maxYD) {
        double mx = -1e100;
        double mn = 1e100;

        if (maxYU != -INF) mx = Math.max(mx, maxYU + t);
        if (maxY0 != -INF) mx = Math.max(mx, maxY0);
        if (maxYD != -INF) mx = Math.max(mx, maxYD - t);

        if (minYU != INF) mn = Math.min(mn, minYU + t);
        if (minY0 != INF) mn = Math.min(mn, minY0);
        if (minYD != INF) mn = Math.min(mn, minYD - t);

        return mx - mn;
    }
}

def solve():
    import sys
    input = sys.stdin.readline

    N = int(input())
    xs = []
    ys = []
    dirs = []

    for _ in range(N):
        x, y, d = input().split()
        xs.append(int(x))
        ys.append(int(y))
        dirs.append(d)

    def width(t):
        xmin = float('inf')
        xmax = -float('inf')
        for x, d in zip(xs, dirs):
            if d == 'R':
                cx = x + t
            elif d == 'L':
                cx = x - t
            else:
                cx = x
            if cx < xmin:
                xmin = cx
            if cx > xmax:
                xmax = cx
        return xmax - xmin

    def height(t):
        ymin = float('inf')
        ymax = -float('inf')
        for y, d in zip(ys, dirs):
            if d == 'U':
                cy = y + t
            elif d == 'D':
                cy = y - t
            else:
                cy = y
            if cy < ymin:
                ymin = cy
            if cy > ymax:
                ymax = cy
        return ymax - ymin

    def area(t):
        return width(t) * height(t)

    lo = 0.0
    hi = 1e8  # large enough

    for _ in range(200):
        m1 = lo + (hi - lo) / 3
        m2 = hi - (hi - lo) / 3
        if area(m1) < area(m2):
            hi = m2
        else:
            lo = m1

    ans = area((lo + hi) / 2)
    print(f"{ans:.10f}")

