import sys

INF = 10**30

def min_abs_linear(lines):
    """
    lines: list of (m, b), value = m*t + b, with m in {-1,0,1}
    Return minimum over t>=0 of max_i(m_i t+b_i) - min_i(m_i t+b_i).
    """
    candidates = {0.0}

    groups = {-1: [], 0: [], 1: []}
    for m, b in lines:
        groups[m].append(b)

    # Extremes that can ever become max/min
    max_line = {}
    min_line = {}
    for m in (-1, 0, 1):
        if groups[m]:
            max_line[m] = max(groups[m])
            min_line[m] = min(groups[m])

    # Candidate times when any pair of extreme lines cross
    max_items = [(m, b) for m, b in max_line.items()]
    min_items = [(m, b) for m, b in min_line.items()]

    all_items = max_items + min_items
    for i in range(len(all_items)):
        m1, b1 = all_items[i]
        for j in range(i + 1, len(all_items)):
            m2, b2 = all_items[j]
            if m1 == m2:
                continue
            t = (b2 - b1) / (m1 - m2)
            if t >= 0:
                candidates.add(t)

    def width(t):
        mx = -INF
        mn = INF
        for m, b in max_items:
            v = m * t + b
            if v > mx:
                mx = v
        for m, b in min_items:
            v = m * t + b
            if v < mn:
                mn = v
        return mx - mn

    ans = INF
    for t in candidates:
        ans = min(ans, width(t))
    return ans

def main():
    input = sys.stdin.readline
    N = int(input())

    x_lines = []
    y_lines = []

    for _ in range(N):
        x, y, d = input().split()
        x = int(x)
        y = int(y)

        if d == 'R':
            x_lines.append((1, x))
            y_lines.append((0, y))
        elif d == 'L':
            x_lines.append((-1, x))
            y_lines.append((0, y))
        elif d == 'U':
            x_lines.append((0, x))
            y_lines.append((1, y))
        else:  # 'D'
            x_lines.append((0, x))
            y_lines.append((-1, y))

    # Candidate times are when x-width or y-width changes form
    candidates = {0.0}

    def collect_times(lines):
        groups = {-1: [], 0: [], 1: []}
        for m, b in lines:
            groups[m].append(b)

        extreme = []
        for m in (-1, 0, 1):
            if groups[m]:
                extreme.append((m, max(groups[m])))
                extreme.append((m, min(groups[m])))

        ts = set()
        for i in range(len(extreme)):
            m1, b1 = extreme[i]
            for j in range(i + 1, len(extreme)):
                m2, b2 = extreme[j]
                if m1 == m2:
                    continue
                t = (b2 - b1) / (m1 - m2)
                if t >= 0:
                    ts.add(t)
        return ts

    candidates |= collect_times(x_lines)
    candidates |= collect_times(y_lines)

    def width(lines, t):
        mx = -INF
        mn = INF
        for m, b in lines:
            v = m * t + b
            if v > mx:
                mx = v
            if v < mn:
                mn = v
        return mx - mn

    ans = float('inf')
    for t in candidates:
        wx = width(x_lines, t)
        wy = width(y_lines, t)
        area = wx * wy
        if area < ans:
            ans = area

    # Result is integer or x.5-based intermediate but final accepted with float precision.
    print("{:.15f}".format(ans).rstrip('0').rstrip('.'))

